import { ListItem } from "@/components/base/list-item/list-item";
import { Button } from "@/components/base/buttons/button";
import { OneAppNavigation } from "@/components/application/oneapp-navigation/oneapp-navigation";
import { NavArrowLeft, EditPencil } from "iconoir-react";
import { TextLink } from "@/components/base/text-link/text-link";
import { Avatar } from "@/components/base/avatar/avatar";
import { CxModal } from "@/components/application/modals/modal";
import { useState } from "react";

const SAMPLE_PHOTO = "/cards-integration/prototypes/avatar-sample.svg";

export default function Screen({ environment }) {
  const [photo, setPhoto] = useState(null);
  const [choosing, setChoosing] = useState(false);

  const choose = (next) => {
    setPhoto(next);
    setChoosing(false);
  };

  return (
    <div className="flex flex-col gap-8 items-stretch w-full -mt-6">
      <div className="flex flex-col gap-4 items-stretch w-full">
        <div className="flex flex-col gap-3 items-center w-full">
          <Avatar
            size="2xl"
            className="size-28"
            src={photo}
            alt={photo ? "Your profile photo" : ""}
            badge={
              <button
                type="button"
                aria-label={photo ? "Change profile photo" : "Add a profile photo"}
                onClick={() => setChoosing(!choosing)}
                className="absolute right-0 bottom-0 flex items-center justify-center rounded-full border-2 border-primary bg-brand-solid p-2"
              >
                <EditPencil className="size-4 text-primary_on-brand" />
              </button>
            }
          />
          <p className="text-display-md font-normal text-brand-primary text-center">Maria Gonzalez</p>
        </div>

        <CxModal
          isOpen={choosing}
          onOpenChange={setChoosing}
          isDismissable
          device={environment === "native" ? "mobile" : "responsive"}
          size="compact"
          content="basic-content"
          title="Profile Photo"
          body="Take a new photo or pick one from your library."
          primaryLabel="Choose from Library"
          onPrimaryAction={() => choose(SAMPLE_PHOTO)}
          secondaryLabel="Take Photo"
          onSecondaryAction={() => choose(SAMPLE_PHOTO)}
          dismissLabel="Cancel"
          onDismissAction={() => setChoosing(false)}
        >
          {photo ? (
            <div className="flex justify-center w-full">
              <TextLink decoration="none" onClick={() => choose(null)}>Remove Current Photo</TextLink>
            </div>
          ) : null}
        </CxModal>
      </div>

      <p className="text-display-lg font-medium text-brand-primary">Profile</p>

      <div className="flex flex-col gap-4 items-stretch w-full">
        <p className="text-display-md font-bold text-brand-primary">Personal Information</p>
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Contact Information</span>} onSelect={() => go("s_tcontact")} />
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Annual Income</span>} onSelect={() => go("s_tincome")} />
      </div>

      <div className="flex flex-col gap-4 items-stretch w-full">
        <p className="text-display-md font-bold text-brand-primary">Settings</p>
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Account Settings</span>} onSelect={() => go("s_tacct")} />
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Notification Settings</span>} onSelect={() => go("s_tnotif")} />
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Security Settings</span>} onSelect={() => go("s_nbo38uwzfa")} />
      </div>

      <div className="flex flex-col gap-4 items-stretch w-full">
        <p className="text-display-md font-bold text-brand-primary">Payments</p>
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Payment Methods</span>} onSelect={() => go("s_tpay")} />
      </div>

      <div className="flex flex-col gap-4 items-stretch w-full">
        <p className="text-display-md font-bold text-brand-primary">Documents</p>
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Billing Statements</span>} onSelect={() => go("s_tbill")} />
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Agreements</span>} onSelect={() => go("s_tagree")} />
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Tax Documents</span>} onSelect={() => go("s_ttax")} />
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Document Upload</span>} onSelect={() => go("s_tupload")} />
      </div>

      <div className="flex flex-col gap-4 items-stretch w-full">
        <p className="text-display-md font-bold text-brand-primary">Other Products</p>
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">BrightWay® Credit Card</span>} />
        <ListItem type="navigation" tile navigationIcon="cx" title={<span className="text-body-default text-brand-primary">Trim by OneMain®</span>} />
      </div>

      <div className="flex justify-center w-full">
        <Button size="sm" color="secondary">Log Out</Button>
      </div>
    </div>
  );
}

export function Header({ scrolled }) {
  return (
    <OneAppNavigation
      surface="mobile-native"
      mobileNativeVariant="menu-bar"
      fillContainer
      nativeMenuPageLevel="secondary"
      nativeMenuState={scrolled ? "scrolling" : "default"}
      nativeMenuPageTitle="Profile"
      nativeMenuShowActions={false}
      onBackPress={() => go("")}
      className="bg-secondary"
    />
  );
}

import { ListItem } from "@/components/base/list-item/list-item";
import { Tile } from "@/components/base/tile/tile";
import { Divider } from "@/components/base/divider/divider";
import { Button } from "@/components/base/buttons/button";
import { OneAppNavigation } from "@/components/application/oneapp-navigation/oneapp-navigation";
import { Toast } from "@/components/base/toast/toast";
import { useState } from "react";

/*
 * Contact information for every account at once.
 *
 * There is no "choose an account" step. The task is the page and each account
 * is a section on it, so the same four fields simply appear once per account.
 * Each section keeps its own stored values and its own Edit screen, which is
 * what the account step used to decide.
 */
const ACCOUNTS = [
  { id: "loan", label: "Loan ****0423", key: "omf.contact.", edit: "s_wdfwx7vkgf" },
  { id: "card", label: "BrightWay ****5675", key: "omf.card.contact.", edit: "s_ck9tb6wzx1" }
];

const GIVEN = {
  "email": "mock-up@example.com",
  "street": "601 NW 2nd Street",
  "city": "Evansville",
  "state": "IN",
  "zip": "47708",
  "phone": "789-258-7890",
  "phone2": "789-258-1456"
};

function stored(key, field) {
  try {
    return sessionStorage.getItem(key + field) || GIVEN[field];
  } catch (e) {
    return GIVEN[field];
  }
}

/** A phone as the app shows it: only the last four. */
function masked(number) {
  const digits = String(number).replace(/[^0-9]/g, "");
  return digits.length < 4 ? number : "***-***-" + digits.slice(-4);
}

function AccountContact({ account }) {
  const key = account.key;
  return (
    <div className="flex flex-col gap-4 items-stretch w-full">
      <p className="text-display-md font-bold text-brand-primary">{account.label}</p>
      <Tile className="gap-0 px-4 py-0">
        <ListItem title={<span className="text-body-default text-brand-primary">Email address</span>} description={stored(key, "email")} wrapDescription />
        <Divider />
        <ListItem
          title={<span className="text-body-default text-brand-primary">Street Address</span>}
          description={<>{stored(key, "street")}<br />{stored(key, "city")}, {stored(key, "state")} {stored(key, "zip")}</>}
          wrapDescription
        />
        <Divider />
        <ListItem title={<span className="text-body-default text-brand-primary">Phone</span>} description={masked(stored(key, "phone"))} />
        <Divider />
        <ListItem title={<span className="text-body-default text-brand-primary">Secondary Phone</span>} description={masked(stored(key, "phone2"))} />
      </Tile>
      <div className="flex justify-center w-full pt-2">
        <Button size="lg" color="primary" onClick={() => go(account.edit)}>Edit</Button>
      </div>
    </div>
  );
}

/** Whether this screen's toast is already counting down; see below. */
let dismissing = false;

/** What the edit screen left behind on its way here, read once and cleared. */
function takeToast() {
  try {
    const message = sessionStorage.getItem("omf.toast");
    if (message) sessionStorage.removeItem("omf.toast");
    return message || "";
  } catch (e) {
    return "";
  }
}

/**
 * Where the device's own chrome ends — the status bar, or a browser's chrome on
 * the web. The toast hangs just under it rather than over the clock, and it is
 * measured because every device draws a different one.
 */
function chromeBottom() {
  try {
    const shell = document.querySelector("[data-proto-os]");
    const chrome = shell ? shell.firstElementChild : null;
    return chrome ? Math.round(chrome.getBoundingClientRect().height) : 0;
  } catch (e) {
    return 0;
  }
}

export default function Screen({ environment }) {
  const [toast, setToast] = useState(takeToast);

  /*
   * A screen may only use useState — the canvas gives it no useEffect — so the
   * toast starts its own countdown on the render that raises it, once, guarded
   * by a module flag. Navigating away remounts the screen and takes it anyway.
   */
  if (toast && !dismissing) {
    dismissing = true;
    setTimeout(() => {
      dismissing = false;
      setToast("");
    }, 5000);
  }

  return (
    <div className="flex flex-col gap-8 items-stretch w-full -mt-4">

      {toast ? (
        <div style={{ position: "fixed", top: chromeBottom(), left: 0, right: 0, zIndex: 2147483647, display: "flex", justifyContent: "center", padding: "12px", pointerEvents: "none" }}>
          <Toast
            data={{ id: "saved", presentation: "cx", color: "success", title: toast }}
            onClose={() => setToast("")}
            className="pointer-events-auto"
          />
        </div>
      ) : null}

      <p className="text-display-lg font-medium text-brand-primary">Contact Information</p>

      {ACCOUNTS.map((account) => <AccountContact key={account.id} account={account} />)}
    </div>
  );
}

export function Header({ scrolled }) {
  return (
    <OneAppNavigation
      surface="mobile-native"
      mobileNativeVariant="menu-bar"
      fillContainer
      nativeMenuPageLevel="secondary"
      nativeMenuState={scrolled ? "scrolling" : "default"}
      nativeMenuPageTitle="Contact Information"
      nativeMenuShowActions={false}
      onBackPress={() => go("s_81wvf53sxa")}
      className="bg-secondary"
    />
  );
}

