import { useState } from "react";
import { ListItem } from "@/components/base/list-item/list-item";
import { Tile } from "@/components/base/tile/tile";
import { Divider } from "@/components/base/divider/divider";
import { OneAppNavigation } from "@/components/application/oneapp-navigation/oneapp-navigation";

/*
 * Account settings for every account at once — no "choose an account" step.
 * The section is its own component so each account keeps its own switches:
 * turning paperless off for the loan leaves the card alone.
 */
const ACCOUNTS = [
  { id: "loan", label: "Loan ****0423" },
  { id: "card", label: "BrightWay ****5675" }
];

function AccountSettings({ account }) {
  const [paperlessBillingStatements, setPaperlessBillingStatements] = useState(true);
  const [emailAlerts, setEmailAlerts] = useState(true);

  return (
    <div className="flex flex-col gap-4 items-stretch w-full">
      <p className="text-display-md font-bold text-brand-primary">{account.label}</p>
      <Tile className="gap-0 px-4 py-0">
        <ListItem onSelect={() => setPaperlessBillingStatements((on) => !on)} type="switch" controlPosition="trailing" isSelected={paperlessBillingStatements} title={<span className="text-body-default text-brand-primary">Paperless Billing Statements</span>} description="Cut the clutter!" />
        <Divider />
        <ListItem onSelect={() => setEmailAlerts((on) => !on)} type="switch" controlPosition="trailing" isSelected={emailAlerts} title={<span className="text-body-default text-brand-primary">Email Alerts</span>} description="Get a reminder when a payment is due." />
      </Tile>
    </div>
  );
}

