import { NavArrowLeft, Bank, CreditCard } from "iconoir-react";
import { ListItem } from "@/components/base/list-item/list-item";
import { Badge } from "@/components/base/badges/badges";
import { Button } from "@/components/base/buttons/button";
import { OneAppNavigation } from "@/components/application/oneapp-navigation/oneapp-navigation";
import { Toast } from "@/components/base/toast/toast";
import { useState } from "react";

/*
 * Payment methods for every account at once — no "choose an account" step.
 * Each section keeps its own default and its own nicknames.
 *
 * Adding is one button at the end rather than one per section: the page is
 * already the whole picture, and which account a new method belongs to is a
 * field on the Add screen, not a choice you make by picking a button.
 */
const ACCOUNTS = [
  {
    id: "loan",
    label: "Loan ****0423",
    defaultKey: "omf.pay.default",
    namePrefix: "omf.pay.name.",
    methods: [
      { key: "m1", kind: "checking", name: "Everyday Checking", detail: "Checking ••••4821", screen: "s_pmedt9bwl5" },
      { key: "m2", kind: "debit", name: "Visa Debit", detail: "Debit card ••••9012", screen: "s_pmedt2rqc8" }
    ]
  },
  {
    id: "card",
    label: "BrightWay ****5675",
    defaultKey: "omf.card.pay.default",
    namePrefix: "omf.card.pay.name.",
    methods: [
      { key: "m1", kind: "checking", name: "Everyday Checking", detail: "Checking ••••4821", screen: "s_cpm3chk7nq" },
      { key: "m2", kind: "debit", name: "Visa Debit", detail: "Debit card ••••9012", screen: "s_cpm4dbt5wy" }
    ]
  }
];

function storedDefault(key) {
  try {
    return sessionStorage.getItem(key) || "m1";
  } catch (e) {
    return "m1";
  }
}

function storedName(prefix, key, given) {
  try {
    return sessionStorage.getItem(prefix + key) || given;
  } catch (e) {
    return given;
  }
}

function Chip({ kind }) {
  return (
    <span className="flex size-10 shrink-0 items-center justify-center rounded-full bg-brand-secondary">
      {kind === "debit" ? <CreditCard className="size-5 text-brand-primary" /> : <Bank className="size-5 text-brand-primary" />}
    </span>
  );
}

function AccountPaymentMethods({ account }) {
  const current = storedDefault(account.defaultKey);

  return (
    <div className="flex flex-col gap-4 items-stretch w-full">
      <p className="text-display-md font-bold text-brand-primary">{account.label}</p>
      {account.methods.map((method) => (
        <ListItem
          key={method.key}
          type="navigation"
          tile
          navigationIcon="cx"
          leadingVisual={<Chip kind={method.kind} />}
          title={<span className="text-body-default text-brand-primary">{storedName(account.namePrefix, method.key, method.name)}</span>}
          description={method.detail}
          trailing={current === method.key ? <Badge size="sm" color="brand">Default</Badge> : null}
          onSelect={() => go(method.screen)}
          wrapDescription
        />
      ))}
    </div>
  );
}

/** Whether this screen's toast is already counting down; see below. */
let dismissing = false;

/** What the edit screen left behind on its way here, read once and cleared. */
function takeToast() {
  try {
    const message = sessionStorage.getItem("omf.toast");
    if (message) sessionStorage.removeItem("omf.toast");
    return message || "";
  } catch (e) {
    return "";
  }
}

/**
 * Where the device's own chrome ends — the status bar, or a browser's chrome on
 * the web. The toast hangs just under it rather than over the clock, and it is
 * measured because every device draws a different one.
 */
function chromeBottom() {
  try {
    const shell = document.querySelector("[data-proto-os]");
    const chrome = shell ? shell.firstElementChild : null;
    return chrome ? Math.round(chrome.getBoundingClientRect().height) : 0;
  } catch (e) {
    return 0;
  }
}

export default function Screen({ environment }) {
  const [toast, setToast] = useState(takeToast);

  /*
   * A screen may only use useState — the canvas gives it no useEffect — so the
   * toast starts its own countdown on the render that raises it, once, guarded
   * by a module flag. Navigating away remounts the screen and takes it anyway.
   */
  if (toast && !dismissing) {
    dismissing = true;
    setTimeout(() => {
      dismissing = false;
      setToast("");
    }, 5000);
  }

  return (
    <div className="flex flex-col gap-8 items-stretch w-full -mt-4">

      {toast ? (
        <div style={{ position: "fixed", top: chromeBottom(), left: 0, right: 0, zIndex: 2147483647, display: "flex", justifyContent: "center", padding: "12px", pointerEvents: "none" }}>
          <Toast
            data={{ id: "saved", presentation: "cx", color: "success", title: toast }}
            onClose={() => setToast("")}
            className="pointer-events-auto"
          />
        </div>
      ) : null}

      <p className="text-display-lg font-medium text-brand-primary">Payment Methods</p>

      {ACCOUNTS.map((account) => <AccountPaymentMethods key={account.id} account={account} />)}

      <div className="flex justify-center w-full">
        <Button size="lg" color="primary" onClick={() => go("s_pmadd6vkr3")}>Add Payment Method</Button>
      </div>
    </div>
  );
}

