/*
 * Billing statements for every account at once — no "choose an account" step.
 * Each section opens on the most recent year and its rows lead to that
 * account's own statement.
 */
const ACCOUNTS = [
  { id: "loan", label: "Loan ****0423", statement: "s_jlqf1b87r5" },
  { id: "card", label: "BrightWay ****5675", statement: "s_ckq6y7fnd9" }
];

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

/* Newest first, and each year runs to the month the account has statements for. */
const YEARS = [
  { year: 2026, newest: 8, oldest: 0 },
  { year: 2025, newest: 11, oldest: 0 },
  { year: 2024, newest: 11, oldest: 3 }
];

/** A statement posts on the first of the month after the one it covers. */
function posted(year, month) {
  const next = month === 11 ? 0 : month + 1;
  return "Posted " + MONTHS[next].slice(0, 3) + " 1, " + (month === 11 ? year + 1 : year);
}

function statementsIn(span) {
  const rows = [];
  for (let month = span.newest; month >= span.oldest; month--) rows.push({ month: MONTHS[month], posted: posted(span.year, month) });
  return rows;
}

function AccountStatements({ account }) {
  return (
    <div className="flex flex-col gap-4 items-stretch w-full">
      <p className="text-display-md font-bold text-brand-primary">{account.label}</p>
      <Accordion variant="card" allowsMultipleExpanded defaultExpandedKeys={["2026"]}>
        {YEARS.map((span) => (
          <Accordion.Item key={span.year} id={String(span.year)}>
            <Accordion.Trigger>{String(span.year)}</Accordion.Trigger>
            <Accordion.Panel>
              {statementsIn(span).map((row, i) => (
                <div key={row.month}>
                  {i > 0 ? <Divider /> : null}
                  <ListItem type="navigation" navigationIcon="cx" title={<span className="text-body-default text-brand-primary">{row.month}</span>} description={row.posted} onSelect={() => go(account.statement)} />
                </div>
              ))}
            </Accordion.Panel>
          </Accordion.Item>
        ))}
      </Accordion>
    </div>
  );
}

