 * Uploading is a task you do *to* an account, so each section is its own
 * component with its own file, its own progress and its own history: a
 * pay stub sent to the loan team never appears under the card.
 */
const ACCOUNTS = [
  {
    id: "loan",
    label: "Loan ****0423",
    team: "loan team",
    history: [
      { name: "Pay-stub-July-2026.pdf", when: "Uploaded Aug 2, 2026", status: "Accepted" },
      { name: "Proof-of-residence.pdf", when: "Uploaded Mar 18, 2024", status: "Accepted" },
