      { name: "Drivers-license.jpg", when: "Uploaded Mar 14, 2024", status: "Accepted" }
    ]
  }
];

/** A document reads as a page, a photo as an image — same chip as the payment methods. */
function FileChip({ name }) {
  const isImage = /\.(jpe?g|png|heic)$/i.test(name);
  return (
    <span className="flex size-10 shrink-0 items-center justify-center rounded-full bg-brand-secondary">
      {isImage ? <MediaImage className="size-5 text-brand-primary" /> : <Page className="size-5 text-brand-primary" />}
    </span>
  );
}

function AccountUpload({ account }) {
  const [name, setName] = useState(null);
  const [step, setStep] = useState("empty");
  const [renaming, setRenaming] = useState(false);
  const [draft, setDraft] = useState("");
  const [history, setHistory] = useState(account.history);

  const choose = (files) => {
    const picked = files && files[0];
    if (!picked) return;
    setName(picked.name);
    setStep("ready");
  };

  const upload = () => {
    setStep("uploading");
    setTimeout(() => {
      setHistory((past) => [{ name, when: "Uploaded just now", status: "In review" }, ...past]);
      setStep("done");
    }, 1400);
  };

  const reset = () => {
    setName(null);
    setRenaming(false);
    setStep("empty");
  };

  const startRename = () => {
    setDraft(name);
    setRenaming(true);
  };

  const saveName = () => {
    const next = draft.trim();
    if (next) setName(next);
    setRenaming(false);
  };

  return (
    <div className="flex flex-col gap-4 items-stretch w-full">
      <p className="text-display-md font-bold text-brand-primary">{account.label}</p>

      {step === "done" ? (
        <Tile className="gap-4">
          <DocumentUploadSubmitted title="You're all set">
            <p>We&rsquo;ve uploaded your document to your {account.team} for review. There&rsquo;s nothing else you need to do right now.</p>
          </DocumentUploadSubmitted>
          <div className="flex">
            <Button size="sm" color="secondary" onClick={reset}>Upload another document</Button>
          </div>
        </Tile>
      ) : (
        <Tile className="gap-4">
          <DocumentUploadDropZone
            title="Tap to choose a file"
            hint="PDF, JPG, or PNG &middot; up to 10 MB"
            accept=".pdf,.jpg,.jpeg,.png"
            isDisabled={step === "uploading"}
            onDropFiles={choose}
          />

          {name && step === "ready" ? (
            <div className="flex flex-col gap-1 border-b border-secondary py-4 w-full">
              {renaming ? (
                <div className="flex w-full items-center justify-between gap-4">
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <Input aria-label="Document name" value={draft} onChange={setDraft} />
                  </div>
                  <TextLink decoration="none" weight="regular" onClick={saveName}>Save</TextLink>
                </div>
              ) : (
                <div className="flex w-full items-center justify-between gap-4">
                  <span className="min-w-0 truncate text-body-default text-brand-primary">{name}</span>
                  <div className="flex items-center gap-3 shrink-0">
                    <TextLink decoration="none" weight="regular" onClick={startRename}>Rename</TextLink>
                    <Divider orientation="vertical" className="shrink-0" style={{ height: 16, width: 1 }} />
                    <TextLink decoration="none" weight="regular" onClick={reset}>Remove</TextLink>
                  </div>
                </div>
              )}
            </div>
          ) : null}

          {name && step === "uploading" ? (
            <DocumentUploadFileList>
              <DocumentUploadFileRow name={name} status="uploading" />
            </DocumentUploadFileList>
          ) : null}

          {step === "ready" && !renaming ? (
            <div className="flex">
              <Button size="sm" color="primary" onClick={upload}>Upload document</Button>
            </div>
          ) : null}

          <p className="text-body-supporting text-secondary">
            Files are encrypted in transit and shared only with your {account.team}.
          </p>
        </Tile>
      )}

      <p className="text-body-default font-bold text-brand-primary">Document History</p>
      <Tile className="gap-0 px-4 py-0">
        {history.map((entry, i) => (
          <div key={entry.name + i}>
            {i > 0 ? <Divider /> : null}
            <ListItem
              leadingVisual={<FileChip name={entry.name} />}
              title={<span className="text-body-default text-brand-primary">{entry.name}</span>}
              description={entry.when}
              trailing={entry.status}
            />
          </div>
        ))}
      </Tile>
    </div>
  );
}

