import { Button } from "@/components/base/buttons/button";
import { OneAppNavigation } from "@/components/application/oneapp-navigation/oneapp-navigation";

const KEY = "omf.income.";
const GIVEN = {
  "amount": "$68,500",
  "source": "employment",
  "employer": "Ridgeline Logistics",
  "frequency": "biweekly",
  "other": "$4,800",
  "updatedOn": "March 12, 2026"
};
const SOURCES = [
  {
    "id": "employment",
    "label": "Employment"
  },
  {
    "id": "self-employed",
    "label": "Self-employed"
  },
  {
    "id": "retirement",
    "label": "Retirement or pension"
  },
  {
    "id": "benefits",
    "label": "Benefits"
  },
  {
    "id": "other",
    "label": "Other"
  }
];
const FREQUENCIES = [
  {
    "id": "weekly",
    "label": "Weekly"
  },
  {
    "id": "biweekly",
    "label": "Every two weeks"
  },
  {
    "id": "semimonthly",
    "label": "Twice a month"
  },
  {
    "id": "monthly",
    "label": "Monthly"
  }
];

function stored(field) {
  try {
    return sessionStorage.getItem(KEY + field) || GIVEN[field];
  } catch (e) {
    return GIVEN[field];
  }
}

function remember(field, value) {
  try {
    sessionStorage.setItem(KEY + field, value);
  } catch (e) {}
}

/** What the person picked, in the words the list shows. */
function labelOf(items, id) {
  const found = items.filter((item) => item.id === id)[0];
  return found ? found.label : id;
}

function savedTitle(fields) {
  if (fields.length === 0) return "No changes to save";
  if (fields.length === 1) return fields[0] + " saved";
  if (fields.length === 2) return fields[0] + " and " + fields[1].toLowerCase() + " saved";
  return fields.length + " changes saved";
}

export default function Screen({ environment }) {
  const [amount, setAmount] = useState(stored("amount"));
  const [source, setSource] = useState(stored("source"));
  const [employer, setEmployer] = useState(stored("employer"));
  const [frequency, setFrequency] = useState(stored("frequency"));
  const [other, setOther] = useState(stored("other"));

  const edit = (set, value) => set(value);

  const save = () => {
    const fields = [
      ["amount", amount, "Annual Income"],
      ["source", source, "Income Source"],
      ["employer", employer, "Employer"],
      ["frequency", frequency, "Pay Frequency"],
      ["other", other, "Other Annual Income"],
    ];
    const changed = [];
    for (const [key, value, label] of fields) {
      if (value === stored(key)) continue;
      remember(key, value);
      changed.push(label);
    }
    // What the person will see on the screen behind this one.
    if (changed.length) remember("updatedOn", new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }));
    /*
     * The read-only view is where the change shows, so that is where it gets
     * confirmed: the message travels with the screen change, and nothing is
     * said when nothing changed.
     */
    try {
      if (changed.length) sessionStorage.setItem("omf.toast", savedTitle(changed));
    } catch (e) {}
    go("s_tincome");
  };

  return (
    <div className="flex flex-col gap-8 items-stretch w-full">


      <p className="text-display-lg font-medium text-brand-primary">Loan ****0423</p>

      <div className="flex flex-col gap-4 items-stretch w-full">
