        <Tile className="gap-0 px-4 py-0">
          <div className="py-4">
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Annual income before taxes</span>
              <Input aria-label="Annual income before taxes" value={amount} onChange={(next) => edit(setAmount, next)} />
            </div>
          </div>
          <Divider />
          <div className="flex flex-col gap-3 py-4">
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Income source</span>
              <Select aria-label="Income source" items={SOURCES} selectedKey={source} onSelectionChange={(key) => edit(setSource, String(key))}>
                {(item) => <Select.Item id={item.id}>{item.label}</Select.Item>}
              </Select>
            </div>
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Employer</span>
              <Input aria-label="Employer" value={employer} onChange={(next) => edit(setEmployer, next)} />
            </div>
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Pay frequency</span>
              <Select aria-label="Pay frequency" items={FREQUENCIES} selectedKey={frequency} onSelectionChange={(key) => edit(setFrequency, String(key))}>
                {(item) => <Select.Item id={item.id}>{item.label}</Select.Item>}
              </Select>
            </div>
          </div>
          <Divider />
          <div className="py-4">
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Other annual income</span>
              <Input aria-label="Other annual income" value={other} onChange={(next) => edit(setOther, next)} />
              <span className="text-body-supporting text-brand-secondary">Alimony, child support and other income need not be disclosed unless you want it considered.</span>
            </div>
          </div>
          <Divider />
          <div className="flex py-4">
            <Button size="sm" color="primary" onClick={save}>Save</Button>
          </div>
        </Tile>
      </div>
    </div>
  );
}

