const DEFAULT_KEY = "omf.pay.default";

function storedDefault() {
  try {
    return sessionStorage.getItem(DEFAULT_KEY) || "m1";
  } catch (e) {
    return "m1";
  }
}

function rememberDefault(key) {
  try {
    sessionStorage.setItem(DEFAULT_KEY, key);
  } catch (e) {}
}

const MY_KEY = "m1";
const NAME_KEY = "omf.pay.name.m1";
const GIVEN_NAME = "Everyday Checking";

function storedName() {
  try {
    return sessionStorage.getItem(NAME_KEY) || GIVEN_NAME;
  } catch (e) {
    return GIVEN_NAME;
  }
}

function rememberName(name) {
  try {
    sessionStorage.setItem(NAME_KEY, name);
  } catch (e) {}
}

function savedTitle(fields) {
  if (fields.length === 0) return "No changes to save";
  if (fields.length === 1) return fields[0] + " saved";
  return fields[0] + " and " + fields[1].toLowerCase() + " saved";
}

export default function Screen({ environment }) {
  const [wasDefault, setWasDefault] = useState(storedDefault() === MY_KEY);
  const [isDefault, setIsDefault] = useState(wasDefault);
