  const rename = (value) => {
    setNickname(value);
  };

  const chooseDefault = (value) => {
    setIsDefault(value);
  };

  const save = () => {
    const name = nickname.trim() || GIVEN_NAME;
    const fields = [];
    if (name !== storedName()) fields.push("Nickname");
    if (isDefault && !wasDefault) fields.push("Default payment method");
    setNickname(name);
    rememberName(name);
    if (isDefault) {
      rememberDefault(MY_KEY);
      setWasDefault(true);
    }
    /*
     * The read-only view is where the change shows, so that is where it gets
     * confirmed: the message travels with the screen change, and nothing is
     * said when nothing changed.
     */
    try {
      if (fields.length) sessionStorage.setItem("omf.toast", savedTitle(fields));
    } catch (e) {}
    go("s_tpay");
  };

  return (
    <div className="flex flex-col gap-8 items-stretch w-full">


      <p className="text-display-lg font-medium text-brand-primary">Loan ****0423</p>

