import { useState } from "react";
import { Tile } from "@/components/base/tile/tile";
import { NavArrowLeft } from "iconoir-react";
import { Divider } from "@/components/base/divider/divider";
import { Input } from "@/components/base/input/input";
import { Select } from "@/components/base/select/select";
import { Button } from "@/components/base/buttons/button";
import { OneAppNavigation } from "@/components/application/oneapp-navigation/oneapp-navigation";

const KEY = "omf.contact.";
const GIVEN = {
  "email": "mock-up@example.com",
  "street": "601 NW 2nd Street",
  "city": "Evansville",
  "state": "IN",
  "zip": "47708",
  "phone": "789-258-7890",
  "phone2": "789-258-1456"
};

function stored(field) {
  try {
    return sessionStorage.getItem(KEY + field) || GIVEN[field];
  } catch (e) {
    return GIVEN[field];
  }
}

function remember(field, value) {
  try {
    sessionStorage.setItem(KEY + field, value);
  } catch (e) {}
}

/** A phone as the app shows it: only the last four. */
function masked(number) {
  const digits = String(number).replace(/[^0-9]/g, "");
  return digits.length < 4 ? number : "***-***-" + digits.slice(-4);
}

const STATES = [{"id":"IN","label":"IN"},{"id":"IL","label":"IL"},{"id":"KY","label":"KY"},{"id":"OH","label":"OH"},{"id":"TN","label":"TN"}];

function savedTitle(fields) {
  if (fields.length === 0) return "No changes to save";
  if (fields.length === 1) return fields[0] + " saved";
  if (fields.length === 2) return fields[0] + " and " + fields[1].toLowerCase() + " saved";
  return fields.length + " changes saved";
}

export default function Screen({ environment }) {
  const [email, setEmail] = useState(stored("email"));
  const [street, setStreet] = useState(stored("street"));
  const [city, setCity] = useState(stored("city"));
  const [state, setState] = useState(stored("state"));
  const [zip, setZip] = useState(stored("zip"));
  const [phone, setPhone] = useState(stored("phone"));
  const [phone2, setPhone2] = useState(stored("phone2"));

  /** Editing anything takes the last confirmation down: it was about what was there before. */
  const edit = (set, value) => set(value);

  const save = () => {
    const fields = [
      ["email", email, "Email Address"],
      ["street", street, "Street Address"],
      ["city", city, "City"],
      ["state", state, "State"],
      ["zip", zip, "ZIP Code"],
      ["phone", phone, "Phone"],
      ["phone2", phone2, "Secondary Phone"],
    ];
    const changed = [];
    for (const [key, value, label] of fields) {
      if (value === stored(key)) continue;
      remember(key, value);
      changed.push(label);
    }
    /*
     * The read-only view is where the change shows, so that is where it gets
     * confirmed: the message travels with the screen change, and nothing is
     * said when nothing changed.
     */
    try {
      if (changed.length) sessionStorage.setItem("omf.toast", savedTitle(changed));
    } catch (e) {}
    go("s_tcontact");
  };

  return (
    <div className="flex flex-col gap-8 items-stretch w-full -mt-4">


      <p className="text-display-lg font-medium text-brand-primary">Loan ****0423</p>

      <div className="flex flex-col gap-4 items-stretch w-full">
        <p className="text-display-md font-bold text-brand-primary">Contact Information</p>
        <Tile className="gap-0 px-4 py-0">
          <div className="py-4">
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Email address</span>
              <Input aria-label="Email address" value={email} onChange={(next) => edit(setEmail, next)} />
            </div>
          </div>
          <Divider />
          <div className="flex flex-col gap-3 py-4">
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Street Address</span>
              <Input aria-label="Street Address" value={street} onChange={(next) => edit(setStreet, next)} />
            </div>
            <div className="flex gap-3 items-end">
              <div className="flex-1"><Input aria-label="City" value={city} onChange={(next) => edit(setCity, next)} /></div>
              <Select aria-label="State" items={STATES} selectedKey={state} onSelectionChange={(key) => edit(setState, String(key))}>
                {(item) => <Select.Item id={item.id}>{item.label}</Select.Item>}
              </Select>
            </div>
            <Input aria-label="ZIP code" value={zip} onChange={(next) => edit(setZip, next)} />
          </div>
          <Divider />
          <div className="py-4">
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Phone</span>
              <Input aria-label="Phone" value={phone} onChange={(next) => edit(setPhone, next)} />
            </div>
          </div>
          <Divider />
          <div className="py-4">
            <div className="flex flex-col gap-1">
              <span className="text-body-default text-brand-primary">Secondary Phone</span>
              <Input aria-label="Secondary Phone" value={phone2} onChange={(next) => edit(setPhone2, next)} />
            </div>
          </div>
          <Divider />
          <div className="flex py-4">
            <Button size="sm" color="primary" onClick={save}>Save</Button>
          </div>
        </Tile>
      </div>
    </div>
  );
}

